   */
  def put_concrete_inputs(resolution : Mining_Cargo_Transfer_Supervisor.TransferResolution): Unit = {
    put_resolution(resolution)
  }


  /** helper function to check TransferCommandDerivation_supervisionProcess_transferCommandDerivation's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param command method that will be called with the value of the outgoing data
   *        port 'command'.
   */
  def check_concrete_output(command: Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val commandValue: Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type = get_command().get
    if(!command(commandValue)) {
      testFailures = testFailures :+ st"'command' did not match expected: value of the outgoing data port is ${commandValue}"
