  }

  // getter for out DataPort
  def get_command(): Option[Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type] = {
    val value: Option[Mining_Cargo_Transfer_Supervisor.CargoTransferCommand.Type] = get_command_payload() match {
      case Some(Mining_Cargo_Transfer_Supervisor.CargoTransferCommand_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port command.  Expecting 'Mining_Cargo_Transfer_Supervisor.CargoTransferCommand_Payload' but received ${v}")
